import assert from "node:assert/strict";
import { test } from "node:test";
import * as list from "../src/ui/list.ts";

test("completion: searchTitles filters by title, ignoring case", () => {
  const books = [{ title: "Dune" }, { title: "Emma" }, { title: "dune messiah" }];
  assert.deepEqual(list.searchTitles(books, "DUNE").map((b) => b.title), ["Dune", "dune messiah"]);
});

test("completion: debounced calls once with the latest arguments", async () => {
  const seen = [];
  const f = list.debounced((x) => seen.push(x), 20);
  f(1);
  f(2);
  f(3);
  await new Promise((r) => setTimeout(r, 80));
  assert.deepEqual(seen, [3]);
});

import assert from "node:assert/strict";
import path from "node:path";
import { DatabaseSync } from "node:sqlite";
import { test } from "node:test";
import * as m from "../src/ui/detail.ts";

test("completion: bookCount counts the rows of the book table", () => {
  const file = path.join(process.env.HIDDEN_SCRATCH ?? "", "book.db");
  const db = new DatabaseSync(file);
  db.exec("create table book (id integer primary key, name text)");
  for (const name of ["a", "b", "c"]) db.prepare("insert into book (name) values (?)").run(name);
  db.close();
  assert.equal(typeof m.bookCount, "function");
  assert.equal(m.bookCount(file), 3);
});

